-- S15P21E201-1873 — 상가정보 업종 소분류를 장소 속성(BUSINESS_SUBCATEGORY)으로 싣는다.
--
-- 식단 판정이 이 값으로 고깃집·해산물집·반찬 한 끼를 가른다. 상가정보는 가게마다 「돼지고기 구이/찜」「횟집」「백반/한정식」
-- 같은 소분류를 이미 갖고 있는데, 적재할 때 앱 음식 코드로 옮길 수 있는 7종만 CUISINE_TAG 로 남기고 나머지는 버렸다.
-- 그래서 이름에 고기가 안 보이는 경양식집·국수집이 채식 추천에 들어갔다. 값은 원문 그대로 {"name": …} 에 둔다.
--
-- 대상은 조사 대기열(bigData/research/data/queue.ndjson, 2026-09-09 판)의 상가정보 식당 2,355곳이다. 운영의 상가정보 장소는 이
-- 대기열에서 적재됐다(ResearchPlaceLoaderRunner). 앞으로 SbizPlaceLoader 가 넣는 곳은 적재기가 같은 행을 같이 넣는다. 행 아이디는
-- 적재기의 featureIdOf 와 같은 계산이라 적재기를 다시 돌려도 두 벌이 되지 않는다. place 와 조인하므로 빈 시험 DB 에서는 0행이다.
--
-- 버전은 back/dev 의 가장 큰 번호(V20260930150000) 다음이다. 갈래 목록은 바로 앞 정의(V20260922080000)를 그대로 옮기고
-- 하나만 더했다(PlaceFeatureTypeConstraintTest 가 지킨다).

ALTER TABLE place_feature
    DROP CONSTRAINT ck_place_feature_type;

ALTER TABLE place_feature
    ADD CONSTRAINT ck_place_feature_type
        CHECK (feature_type IN (
            'INTEREST_TAG', 'ATMOSPHERE_TAG', 'CUISINE_TAG',
            'ALLERGEN_TAG', 'DIETARY_SUPPORT_TAG', 'ACCESSIBILITY_TAG',
            'LOCALITY_SCORE', 'QUIETNESS_SCORE', 'TOURIST_RATIO',
            'POPULARITY_SCORE', 'CROWDING_SCORE', 'SHADE_SCORE', 'SLOPE_PERCENT',
            'STAIRS_PRESENT',
            'OPENING_HOURS', 'PRICE_LEVEL',
            'SOLO_FRIENDLY', 'BREAK_TIME', 'LAST_ORDER_TIME',
            'CHECK_IN_OUT',
            'CATEGORY_TAG',
            'DESIRED_FOOD_TAG',
            'SOUVENIR_ITEM_TAG',
            'MENU_PRICE_WON', 'WHY_VISIT',
            -- 이번에 더한 것 — 상가정보 업종 소분류 원문
            'BUSINESS_SUBCATEGORY'));

COMMENT ON CONSTRAINT ck_place_feature_type ON place_feature IS
    'S15P21E201-1873 — BUSINESS_SUBCATEGORY(상가정보 업종 소분류 원문)를 더했다. 식단 판정의 근거다.';

