JOIN place p ON p.source_type = 'SBIZ' AND p.source_id = seed.store_id
WHERE NOT EXISTS (
    SELECT 1 FROM place_feature f
    WHERE f.place_id = p.place_id AND f.feature_type = 'BUSINESS_SUBCATEGORY'
)
ON CONFLICT (place_feature_id) DO NOTHING;

